#include "ComponentMetadataCatalogue.hpp"
namespace elysium::ecs {bool ComponentMetadataCatalogue::add(ComponentMeta m,std::string&w){if(!m.type||!m.schemaVersion||!m.owner){w="invalid component metadata";return false;}return rows_.emplace(m.type,std::move(m)).second;}bool ComponentMetadataCatalogue::lint(std::vector<std::string>&e)const{for(auto&[id,m]:rows_){if(m.persistence!=PersistenceClass::No&&(m.containsRawEntity||m.rawPointer||m.jobHandle||m.gpuHandle||m.iterationIndex))e.push_back("persistent component contains forbidden transient reference");if(m.persistence==PersistenceClass::Derived&&m.rebuildInputs.empty())e.push_back("derived component missing rebuild input");if(m.persistence==PersistenceClass::No&&!m.rebuildInputs.empty())e.push_back("NO component should not claim durable rebuild authority");}return e.empty();}std::optional<ComponentMeta>ComponentMetadataCatalogue::get(ContentId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;}}
